import boto3

bedrock = boto3.client('bedrock-runtime')

def invoke_model(prompt, model_id='amazon.titan-image-generator-v1'):
    body = {
        'taskType': 'TEXT_IMAGE_GENERATION',
        'textToGenerateImage': prompt,
        'imageGenerationConfig': {
            'numberOfImages': 1,
            'quality': 'standard',
            'cfgScale': 10,
            'height': 512,
            'width': 512
        }
    }

    response = bedrock.invoke_model(
        body=json.dumps(body),
        modelId=model_id,
        accept='application/json',
        contentType='application/json'
    )

    response_body = json.loads(response.get('body').read())
    return response_body

def normalize_response(response):
    images = response.get('images', [])
    normalized_images = []
    for image in images:
        normalized_image = {
            'image_data': image.get('imageData', ''),
            'seed': image.get('seed', 0)
        }
        normalized_images.append(normalized_image)
    return normalized_images

import boto3

def create_rekognition_client():
    return boto3.client('rekognition')

def detect_labels(image, max_labels=10, min_confidence=90.0):
    client = create_rekognition_client()
    response = client.detect_labels(
        Image={'Bytes': image},
        MaxLabels=max_labels,
        MinConfidence=min_confidence
    )
    return response['Labels']

def detect_text(image):
    client = create_rekognition_client()
    response = client.detect_text(
        Image={'Bytes': image}
    )
    return response['TextDetections']

